/*
 * Regenerates puzzles.js from puzzles.json.
 *
 * puzzles.json is the source of truth. The game fetches it when served over
 * http, but fetch() is blocked on file:// URLs, so puzzles.js carries an
 * embedded copy for the double-click-the-html case.
 *
 * Run:  node bundle.js       (after editing puzzles.json)
 */
const fs = require("fs");
const path = require("path");

const jsonPath = path.join(__dirname, "puzzles.json");
const jsPath = path.join(__dirname, "puzzles.js");

const data = JSON.parse(fs.readFileSync(jsonPath, "utf8"));

// Not pretty-printed: this is a generated mirror, and indenting a large
// archive roughly triples the file the browser has to pull down.
const out = `/* GENERATED by bundle.js — edit puzzles.json instead, then re-run it. */
const PUZZLES_EMBEDDED = ${JSON.stringify(data)};
`;

fs.writeFileSync(jsPath, out);
const kb = (fs.statSync(jsPath).size / 1024).toFixed(0);
console.log(`✓ puzzles.js written from puzzles.json (${data.length} puzzles, ${kb} KB)`);
